<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('SHIPMENT_MANAGE');$aid=(int)($_GET['assignment_id']??0);$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid token.';else try{$st=[];for($i=0;$i<3;$i++)$st[]=['name'=>$_POST['stop_name'][$i]??'','address'=>$_POST['stop_address'][$i]??'','city'=>$_POST['stop_city'][$i]??''];$id=DispatchService::create($aid,$_POST['departure']??'',$_POST['arrival']??'',$st,(int)Auth::user()['id']);header('Location: '.Url::to('operations/trip-view.php?id='.$id.'&created=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Plan Shipment';require BASE_PATH.'/app/Views/layout/header.php';?><h1>Plan shipment & trip</h1><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form method="post" class="card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><div class="form-grid"><div class="field"><label>Planned departure</label><input type="datetime-local" name="departure" required></div><div class="field"><label>Planned arrival</label><input type="datetime-local" name="arrival" required></div></div><h3>Optional intermediate stops</h3><?php for($i=0;$i<3;$i++):?><div class="form-grid"><div class="field"><input name="stop_name[]" placeholder="Stop name"></div><div class="field"><input name="stop_address[]" placeholder="Address"></div><div class="field"><input name="stop_city[]" placeholder="City"></div></div><?php endfor;?><button class="button">Create planned shipment & trip</button></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
